class Solution { public:long long maxSpending(vector<vector<int>>& values){using Item=array<int,3>;priority_queue<Item,vector<Item>,greater<Item>> heap;for(int row=0;row<(int)values.size();++row){int column=values[row].size()-1;heap.push({values[row][column],row,column});}long long answer=0,day=1;while(!heap.empty()){auto [value,row,column]=heap.top();heap.pop();answer+=day++*value;if(column>0)heap.push({values[row][column-1],row,column-1});}return answer;} };
